<template>
  <!-- iz-app opts this subtree into the theme's primitive layer: it supplies the
       generic token names these widgets read (see server.css §8 "App token
       bridge") and is the ancestor the .iz-app-scoped primitives require. -->
  <div class="emp-dashboard iz-app">
    <!-- No Organization State -->
    <div v-if="!data.organization" class="iz-empty emp-dashboard__empty">
      <div class="emp-dashboard__empty-icon">
        <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
          <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
          <circle cx="9" cy="7" r="4" />
          <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
          <path d="M16 3.13a4 4 0 0 1 0 7.75" />
        </svg>
      </div>
      <h2 class="emp-dashboard__empty-title">No Organization Found</h2>
      <p class="emp-dashboard__empty-text">
        Your account is not associated with any organization.<br />
        Please contact your administrator.
      </p>
    </div>

    <template v-else>
      <!-- 1. Welcome Strip -->
      <!-- 1+2. One sticky header: identity and counts on top, the project
           switcher below, filters folding away between them once it sticks. -->
      <DashboardHeader
        :employee="data.employee"
        :organization="data.organization"
        :focus-now="derivedFocusNow"
        :workload="derivedWorkload"
        :projects="data.projects"
        :tasks="data.tasks"
        :active-project-id="activeProjectId"
        @filter="onFocusFilter"
        @filter-project="onProjectFilter"
        :active-view="activeView"
        @switch-view="onSwitchView"
      />

      <template v-if="activeView === 'overview'">
        <!-- 2.5 Map of all (or filtered) project locations -->
        <ProjectsMapWidget
          :projects="mapProjects"
          :active-project-id="activeProjectId"
          @filter-project="onProjectFilter"
        />

        <ProjectPortfolioPanel :organization-id="Number(data.organization.id)" />

        <!-- 3. Primary Focus Area -->
        <section class="emp-dashboard__focus-row">
          <FocusNowWidget :focus="derivedFocusNow" :events="data.upcomingEvents || []" @filter="onFocusFilter" @select-task="onSelectTask" />
          <div class="emp-dashboard__focus-side">
            <WorkloadWidget :workload="derivedWorkload" @filter="onFocusFilter" />
            <ScheduleWidget :schedule="derivedSchedule" @filter="onFocusFilter" />
          </div>
        </section>

        <WaitingOnYouWidget
          :mentions="data.unreadMentions || []"
          @switch-view="onSwitchView"
        />

        <!-- A. My Week Panel -->
        <MyWeekWidget :tasks="filteredTasks" @select-task="onSelectTask" @filter-project="onProjectFilter" />

        <!-- B. My Tasks Board -->
        <TasksBoardWidget ref="tasksBoard" :tasks="filteredTasks" :projects="filteredProjects" :focus-filter="focusFilter" :signatures="data.pendingSignatures || []" :documents="data.outgoingSignatures || []" @filter-project="onProjectFilter" />

        <!-- B2. Gantt Chart -->
        <GanttWidget v-if="activeProjectId === null" :timeline="filteredTimeline" :projects="filteredProjects" />

        <!-- D. Project Context Drawer -->
        <ProjectDrawerWidget :project="selectedProject" :timeline="data.timeline" :activity-events="data.activityEvents || []" :notes="data.notes || []" />
      </template>

      <CardsView
        v-else
        :tasks="filteredTasks"
        :projects="filteredProjects"
        :events="data.upcomingEvents || []"
        :mentions="data.unreadMentions || []"
        :signatures="data.pendingSignatures || []"
        :documents="data.outgoingSignatures || []"
        @select-task="onSelectTask"
        @filter-project="onProjectFilter"
      />
    </template>
  </div>
</template>

<script>
import FocusNowWidget from "./FocusNowWidget.vue";
import WorkloadWidget from "./WorkloadWidget.vue";
import ScheduleWidget from "./ScheduleWidget.vue";
import TasksBoardWidget from "./TasksBoardWidget.vue";
import MyWeekWidget from "./MyWeekWidget.vue";
import GanttWidget from "./GanttWidget.vue";
import DashboardHeader from "./DashboardHeader.vue";
import ProjectDrawerWidget from "./ProjectDrawerWidget.vue";
import ProjectsMapWidget from "./ProjectsMapWidget.vue";
import WaitingOnYouWidget from "./WaitingOnYouWidget.vue";
import CardsView from "./CardsView.vue";

export default {
  name: "Dashboard",
  components: {
    FocusNowWidget,
    WorkloadWidget,
    ScheduleWidget,
    TasksBoardWidget,
    MyWeekWidget,
    GanttWidget,
    DashboardHeader,
    ProjectDrawerWidget,
    ProjectsMapWidget,
    WaitingOnYouWidget,
    CardsView,
    ProjectPortfolioPanel: () => import("./ProjectPortfolioPanel.vue"),
  },
  props: {
    data: { type: Object, required: true },
  },
  data: function () {
    return {
      focusFilter: null,
      selectedProject: null,
      activeProjectId: null,
      activeView: "overview",
    };
  },
  computed: {
    filteredTasks: function () {
      var pid = this.activeProjectId;
      if (pid === null) return this.data.tasks;
      return this.data.tasks.filter(function (t) { return t.projectId === pid; });
    },
    filteredProjects: function () {
      var pid = this.activeProjectId;
      if (pid === null) return this.data.projects;
      return this.data.projects.filter(function (p) { return p.id === pid; });
    },
    mapProjects: function () {
      var locs = (this.data && this.data.projectLocations) || {};
      var out = [];
      this.filteredProjects.forEach(function (p) {
        var loc = locs[p.id];
        if (!loc || loc.lat == null || loc.lng == null) {
          return;
        }
        out.push({
          id: p.id,
          name: p.name,
          number: p.number,
          lat: loc.lat,
          lng: loc.lng,
          displayName: loc.displayName,
        });
      });
      return out;
    },
    filteredTimeline: function () {
      var pid = this.activeProjectId;
      if (pid === null) return this.data.timeline;
      return this.data.timeline.filter(function (i) { return i.projectId === pid; });
    },
    derivedFocusNow: function () {
      var now = new Date();
      var todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      var todayEnd = new Date(todayStart.getTime() + 86400000 - 1);
      var overdue = 0, dueToday = 0, nextTask = null, nextTaskDue = null, oldestTask = null, oldestId = Infinity;
      this.filteredTasks.forEach(function (t) {
        if (t.done) return;
        if (t.duedate) {
          var d = new Date(t.duedate);
          if (d < todayStart) overdue++;
          else if (d <= todayEnd) dueToday++;
          if (d > now && (nextTaskDue === null || d < nextTaskDue)) {
            nextTask = { id: t.id, title: t.title, duedate: t.duedate };
            nextTaskDue = d;
          }
        }
        if (t.id < oldestId) { oldestId = t.id; oldestTask = { id: t.id, title: t.title }; }
      });
      return {
        overdue: overdue,
        dueToday: dueToday,
        nextTask: nextTask,
        oldestTask: oldestTask,
        // Carried straight through from the API rather than re-derived: it
        // counts calendar events left today, not tasks, and events carry no
        // project so activeProjectId must not narrow it. FocusNowWidget reads
        // it off this object, so dropping it here left it undefined and the
        // widget printed "No more events today" above the day's events.
        remainingToday: (this.data.focusNow && this.data.focusNow.remainingToday) || 0,
      };
    },
    derivedWorkload: function () {
      var open = 0, done = 0;
      this.filteredTasks.forEach(function (t) { if (t.done) done++; else open++; });
      var total = open + done;
      return {
        open: open, done: done,
        completionPct: total > 0 ? Math.round((done / total) * 100) : 0,
        // Every project the employee is on, not only status 0. The backend's
        // computeWorkload already counts all of them (despite the field name),
        // and the header's project switcher shows all of them — counting only
        // "Active" here rendered "Projects 0" next to a visible project chip
        // whenever the employee's work sat on a completed project.
        activeProjects: this.filteredProjects.length,
      };
    },
    derivedSchedule: function () {
      var now = new Date();
      var todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      var todayEnd = new Date(todayStart.getTime() + 86400000 - 1);
      var day = now.getDay();
      var weekEnd = new Date(todayStart.getTime() + ((day === 0 ? 0 : 7 - day) + 1) * 86400000 - 1);
      var dueToday = 0, dueThisWeek = 0, noDueDate = 0;
      this.filteredTasks.forEach(function (t) {
        if (t.done) return;
        if (!t.duedate) { noDueDate++; return; }
        var d = new Date(t.duedate);
        if (d >= todayStart && d <= todayEnd) dueToday++;
        if (d >= todayStart && d <= weekEnd) dueThisWeek++;
      });
      var todayStr = todayStart.toISOString().slice(0, 10);
      var nextMilestone = null;
      this.filteredTimeline
        .filter(function (i) { return i.itemType === 'milestone' && i.endDate >= todayStr; })
        .sort(function (a, b) { return a.endDate < b.endDate ? -1 : 1; })
        .slice(0, 1)
        .forEach(function (i) { nextMilestone = { label: i.label, date: i.endDate }; });
      return { dueToday: dueToday, dueThisWeek: dueThisWeek, noDueDate: noDueDate, nextMilestone: nextMilestone };
    },
  },
  mounted: function () {
    try {
      var saved = window.localStorage.getItem("employee_dashboard.activeView");
      if (saved === "cards" || saved === "overview") {
        this.activeView = saved;
      }
    } catch (e) {
      // Private browsing or a blocked store — the default is fine.
    }
  },
  methods: {
    onSwitchView: function (view) {
      this.activeView = view;
      try {
        window.localStorage.setItem("employee_dashboard.activeView", view);
      } catch (e) {
        // Not being able to remember the choice is not worth failing over.
      }
    },
    onFocusFilter: function (tab) {
      var self = this;
      this.focusFilter = { tab: tab, ts: Date.now() };
      // Same reason as onSelectTask: the tasks board these filters drive is an
      // overview widget, so from the card view the header's count badges would
      // otherwise be dead controls.
      this.activeView = "overview";
      this.$nextTick(function () {
        var el = self.$refs.tasksBoard;
        if (el && el.$el) {
          el.$el.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
    },
    onSelectTask: function (taskId) {
      var self = this;
      var task = this.filteredTasks.find(function (t) { return t.id === taskId; });
      if (!task) return;
      var tab = task.done ? "Done" : "All Open";
      this.focusFilter = { tab: tab, taskId: taskId, ts: Date.now() };
      // The tasks board only exists in the overview, so a card-view click has
      // to bring that view back first — otherwise the scroll below finds no
      // ref and the click does nothing at all.
      this.activeView = "overview";
      this.$nextTick(function () {
        var el = self.$refs.tasksBoard;
        if (el && el.$el) {
          el.$el.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
    },
    onProjectFilter: function (projectId) {
      this.activeProjectId = projectId;
      if (projectId !== null) {
        var match = this.data.projects.find(function (p) { return p.id === projectId; });
        this.selectedProject = match || null;
      } else {
        this.selectedProject = null;
      }
    },
  },
};
</script>

<style>
/* ── Nextcloud style isolation ──────────────────────────────── */
/* Page backdrop follows the In Zicht theme. Forcing a light ground here is
   what stops an app following dark mode. */
#app-content:has(.emp-dashboard) {
  background: var(--image-background);
  padding: 0 !important;
  /* The sticky header folds its filter row, which changes the document height
     by ~48px. Scroll anchoring reacts to that by moving scrollTop to keep
     content still — but the header's stuck state is decided from scroll
     position, so the correction pushes it back across the threshold and it
     oscillates. Measured: scrollHeight climbing 2344 -> 2392 through the fold
     with scrollTop jumping to 38 when 20 was requested. Anchoring is the wrong
     help here; the header is meant to change height. */
  overflow-anchor: none;
}
#employee-dashboard-root {
  background: var(--image-background);
  min-height: 100vh;
}

/* Reset headings — Nextcloud adds borders, padding, and themed colors */
