/* Height comes from the wall, not the contents: rows stay aligned and the
   page is the same length for two cards as for sixty. Only the body moves,
   so the title and its count stay legible while the list scrolls. */
.card-panel[data-v-495b5395] {
  height: 340px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow: hidden;
}
.card-panel__head[data-v-495b5395] {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.card-panel__icon[data-v-495b5395] {
  display: flex;
  color: var(--color-text-secondary);
}
.card-panel__title[data-v-495b5395] {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-text-primary);
}
.card-panel__total[data-v-495b5395] { margin-left: auto;
}
.card-panel__controls[data-v-495b5395] {
  flex: none;
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
}
/* min-height: 0 is required — without it a flex child refuses to shrink
   below its content and the body never scrolls. */
.card-panel__body[data-v-495b5395] {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  /* overflow-y:auto forces the computed overflow-x to auto too, so any child
     even a pixel too wide grows a horizontal scrollbar inside the card. */
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  /* Small: each row already pads itself, so a large gap here just wastes the
     card's fixed height and cuts how many rows are readable at once. */
  gap: 2px;
}
.card-panel__empty[data-v-495b5395] {
  flex-shrink: 0;
  margin: auto 0;
  text-align: center;
}
@media (max-width: 900px) {
  /* Released below the wall: nine fixed-height cards in one narrow column
     each trap a scroll gesture, which is unpleasant on touch. */
.card-panel[data-v-495b5395] {
    height: auto;
}
  /* The body must stop being a scroll container too. Leaving a max-height
     here keeps exactly the nested-scroll trap the release exists to remove. */
.card-panel__body[data-v-495b5395] {
    overflow-y: visible;
}
}
