urn {\n      _map: null,\n      _markerGroup: null,\n    };\n  },\n  mounted: function () {\n    if (this.projects.length > 0) {\n      this.initMap();\n    }\n  },\n  beforeDestroy: function () {\n    if (this._map) {\n      this._map.remove();\n      this._map = null;\n      this._markerGroup = null;\n    }\n  },\n  watch: {\n    projects: function (newList) {\n      if (!this._map && newList.length > 0) {\n        this.$nextTick(this.initMap);\n        return;\n      }\n      if (this._map && newList.length === 0) {\n        this._map.remove();\n        this._map = null;\n        this._markerGroup = null;\n        return;\n      }\n      if (this._map) {\n        this.renderMarkers();\n      }\n    },\n  },\n  methods: {\n    initMap: function () {\n      var el = this.$refs.mapRoot;\n      if (!el) {\n        return;\n      }\n      this._map = L.map(el, { scrollWheelZoom: true });\n      L.tileLayer(\"https://tile.openstreetmap.org/{z}/{x}/{y}.png\", {\n        maxZoom: 19,\n        // OSM requires a Referer; override Nextcloud only for tiles, without page paths.\n        referrerPolicy: \"strict-origin\",\n        attribution: '&copy; <a href=\"https://www.openstreetmap.org/copyright\" target=\"_blank\" rel=\"noopener noreferrer\">OpenStreetMap</a> contributors',\n      }).addTo(this._map);\n      this.renderMarkers();\n    },\n    renderMarkers: function () {\n      var self = this;\n      if (this._markerGroup) {\n        this._markerGroup.remove();\n        this._markerGroup = null;\n      }\n      var icon = L.divIcon({\n        className: \"proj-map__marker\",\n        html: MARKER_SVG,\n        iconSize: [28, 28],\n        iconAnchor: [14, 28],\n        popupAnchor: [0, -24],\n      });\n      var markers = [];\n      this.projects.forEach(function (p) {\n        if (p.lat == null || p.lng == null) {\n          return;\n        }\n        var marker = L.marker([p.lat, p.lng], { icon: icon });\n        var label = p.name;\n        if (p.number) {\n          label += \" (\" + p.number + \")\";\n        }\n        var tooltipNode = document.createElement(\"span\");\n        tooltipNode.textContent = label;\n        marker.bindTooltip(tooltipNode, { direction: \"top\", offset: [0, -24] });\n        marker.on(\"click\", function () {\n          self.$emit(\"filter-project\", p.id);\n        });\n        markers.push(marker);\n      });\n\n      if (markers.length === 0) {\n        return;\n      }\n\n      this._markerGroup = L.featureGroup(markers).addTo(this._map);\n\n      if (markers.length === 1) {\n        this._map.setView([this.projects[0].lat, this.projects[0].lng], 14);\n      } else {\n        this._map.fitBounds(this._markerGroup.getBounds(), {\n          padding: [40, 40],\n          maxZoom: 14,\n        });\n      }\n    },\n  },\n};\n</script>\n\n<style scoped>\n.proj-map {  margin-bottom: var(--spacing-lg, 24px);\n  isolation: isolate;\n}\n.proj-map__header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: var(--spacing-md, 16px);\n  color: var(--color-text-primary, #1a1a2e);\n}\n.proj-map__title {\n  font-size: 15px;\n  font-weight: 700;\n}\n.proj-map__count {\n  font-size: 11px;\n  font-weight: 600;\n  background: var(--chart-5-bg);\n  color: var(--chart-5);\n  padding: 2px 8px;\n  border-radius: 8px;\n}\n.proj-map__container {\n  height: 360px;\n  width: 100%;\n  border-radius: 8px;\n  overflow: hidden;\n  background: var(--bg-inset);\n}\n.proj-map__empty {\n  font-size: 13px;\n  color: var(--color-text-muted, #9ca3af);\n  padding: 48px 24px;\n  text-align: center;\n  border: 1px dashed var(--color-border, #e5e7eb);\n  border-radius: 8px;\n}\n</style>\n\n<style>\n.proj-map__marker {\n  background: transparent !important;\n  border: none !important;\n}\n</style>\n"],"sourceRoot":""}]);
