/* Vue 2 needs a single root, but a real box here would break the sticky child:
   an element can only travel within its containing block, and a plain wrapper
   is exactly as tall as its only visible child — zero room to move, so the
   header scrolled away instead of pinning. display:contents makes this element
   generate no box at all, so the sentinel and the sticky wrapper below are laid
   out as children of the dashboard, which is what they were before the sentinel
   was introduced. */
.dash-header-root[data-v-0ff1b03c] {
  display: contents;
}

/* Zero-height trigger. Not display:none — an unrendered element never
   intersects, so the observer would report "stuck" from the start. */
.dash-header__sentinel[data-v-0ff1b03c] {
  height: 0;
  margin: 0;
  padding: 0;
}

/* Wrapper stays in flow so the page does not jump when the card sticks. */
.dash-header-wrap[data-v-0ff1b03c] {
  margin-bottom: var(--spacing-lg, 24px);
  position: sticky;
  top: 0;
  z-index: 100;
}
.dash-header[data-v-0ff1b03c] {
  background: var(--bg-card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

/* Square off the top edge and lift the shadow once it is against the app bar,
   so it reads as attached to the chrome rather than floating over content. */
.dash-header--fixed[data-v-0ff1b03c] {
  border-radius: 0 0 var(--radius-card) var(--radius-card);
  box-shadow: var(--shadow-card-hover);
}

/* Bar, tab, active underline and hover all come from .iz-tabs / .iz-tab —
   only the placement belongs here. */
.dash-header__views[data-v-0ff1b03c] {
  flex-basis: 100%;
  margin-top: 8px;
}

/* ── Tier 1: identity + counts ── */
.dash-header__identity[data-v-0ff1b03c] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px var(--spacing-lg, 24px);
  border-bottom: 1px solid var(--color-border);
}
.dash-header__who[data-v-0ff1b03c] {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.dash-header__who-text[data-v-0ff1b03c] {
  min-width: 0;
}

/* NC core styles bare h2. */
.dash-header__name[data-v-0ff1b03c] {
  margin: 0;
  padding: 0;
  border: none;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dash-header__sub[data-v-0ff1b03c] {
  font-size: 12px;
  color: var(--color-text-secondary);
}
.dash-header__counts[data-v-0ff1b03c] {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

/* These filter the task board, so they have to look pressable. */
.dash-header__count[data-v-0ff1b03c] {
  cursor: pointer;
  text-transform: none;
}

/* ── The folding filter row ──
   grid-template-rows 1fr -> 0fr animates a height the content decides;
   height:auto cannot be transitioned. The inner element needs min-height:0 or
   it refuses to shrink below its content. */
.dash-header__fold[data-v-0ff1b03c] {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 0.22s ease;
}
.dash-header__fold--closed[data-v-0ff1b03c] {
  grid-template-rows: 0fr;
}
.dash-header__fold-inner[data-v-0ff1b03c] {
  overflow: hidden;
  min-height: 0;
}
.dash-header__toolbar[data-v-0ff1b03c] {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  padding: 10px var(--spacing-lg, 24px) 0;
}

/* Chrome from .iz-input; only this field's fixed width is local. */
.dash-header__search[data-v-0ff1b03c] {
  width: 200px;
}

/* Chrome from .iz-select. width:auto because the primitive is width:100% —
   right for a stacked form, wrong for these sitting in a toolbar row. */
.dash-header__select[data-v-0ff1b03c] {
  width: auto;
  cursor: pointer;
}
.dash-header__clear[data-v-0ff1b03c] {
  color: var(--color-badge-danger-text);
}

/* Chrome for the chips themselves is .iz-chip — including the tone tints,
   which by design only appear once a chip is active, so an untouched row
   stays quiet. Only the group's own box is local. */
.dash-header__bands[data-v-0ff1b03c] {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 6px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-el);
  background: var(--bg-card);
  transition: border-color 0.15s ease;
}
.dash-header__bands[data-v-0ff1b03c]:hover {
  border-color: var(--accent);
}
.dash-header__bands > svg[data-v-0ff1b03c] {
  color: var(--accent);
  flex-shrink: 0;
  margin: 0 3px 0 2px;
}
.dash-header__bands .iz-chip[disabled][data-v-0ff1b03c] {
  opacity: 0.38;
  cursor: default;
}
.dash-header__band-n[data-v-0ff1b03c] {
  font-size: 10px;
  font-weight: 600;
  opacity: 0.72;
  font-variant-numeric: tabular-nums;
}

/* ── Tier 2: the project switcher ── */
.dash-header__projects[data-v-0ff1b03c] {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px var(--spacing-lg, 24px) 12px;
}
.dash-header__project-count[data-v-0ff1b03c] {
  flex-shrink: 0;
}
.dash-header__strip[data-v-0ff1b03c] {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  flex: 1;
  min-width: 0;
  padding-bottom: 2px;
  scrollbar-width: thin;
}
.dash-header__strip[data-v-0ff1b03c]::-webkit-scrollbar {
  height: 4px;
}
.dash-header__strip[data-v-0ff1b03c]::-webkit-scrollbar-thumb {
  background: var(--color-border-strong);
  border-radius: 2px;
}
.dash-header__tab[data-v-0ff1b03c] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  padding: 5px 12px;
  border: 1.5px solid transparent;
  border-radius: var(--radius-pill);
  background: var(--bg-subtle);
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  color: var(--color-text-secondary);
  cursor: pointer;
  white-space: nowrap;
  min-height: 0;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}
.dash-header__tab[data-v-0ff1b03c]:hover {
  background: var(--bg-inset);
}
.dash-header__tab--active[data-v-0ff1b03c] {
  background: var(--accent-bg);
  color: var(--accent-on-bg);
  border-color: var(--accent);
}
.dash-header__tab-dot[data-v-0ff1b03c] {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--color-text-muted);
}
.dash-header__tab-dot--active[data-v-0ff1b03c] { background: var(--color-success);
}
.dash-header__tab-dot--completed[data-v-0ff1b03c] { background: var(--chart-5);
}
.dash-header__tab-dot--archived[data-v-0ff1b03c] { background: var(--color-text-muted);
}
.dash-header__tab-name[data-v-0ff1b03c] {
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 180px;
}
.dash-header__tab-num[data-v-0ff1b03c] {
  font-size: 10px;
  color: var(--color-text-muted);
  font-variant-numeric: tabular-nums;
}

/* Without this the band filter is a black box: chips vanish and you take the
   range on faith. With it the strip doubles as a completion overview. */
.dash-header__tab-pct[data-v-0ff1b03c] {
  font-family: var(--iz-font-mono);
  font-size: 10.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  padding-left: 6px;
  border-left: 1px solid var(--color-border-dark);
}
.dash-header__tab-pct--danger[data-v-0ff1b03c] { color: var(--color-badge-danger-text);
}
.dash-header__tab-pct--warning[data-v-0ff1b03c] { color: var(--color-badge-warning-text);
}
.dash-header__tab-pct--accent[data-v-0ff1b03c] { color: var(--accent-on-bg);
}
.dash-header__tab-pct--success[data-v-0ff1b03c] { color: var(--color-badge-success-text);
}
.dash-header__tab-pct--none[data-v-0ff1b03c] {
  color: var(--color-text-muted);
  font-weight: 500;
}
.dash-header__strip-empty[data-v-0ff1b03c] {
  font-size: 12px;
  color: var(--color-text-muted);
  padding: 5px 2px;
}
.dash-header__filter-toggle[data-v-0ff1b03c] {
  flex-shrink: 0;
  min-height: 0;
}

/* A folded filter row can hide an active filter, which would make the project
   list look wrong for no visible reason. Mark the button when that is so. */
.dash-header__filter-toggle--on[data-v-0ff1b03c] {
  color: var(--accent);
  border-color: var(--accent);
}
@media (prefers-reduced-motion: reduce) {
.dash-header__fold[data-v-0ff1b03c],
  .dash-header__tab[data-v-0ff1b03c] {
    transition: none;
}
}
@media (max-width: 700px) {
.dash-header__identity[data-v-0ff1b03c],
  .dash-header__toolbar[data-v-0ff1b03c],
  .dash-header__projects[data-v-0ff1b03c] {
    padding-left: var(--spacing-md, 16px);
    padding-right: var(--spacing-md, 16px);
}
.dash-header__search[data-v-0ff1b03c] {
    width: 100%;
}
}
