}
.tasks-board__header[data-v-d5100cc6] { display: flex; align-items: center; gap: 10px; margin-bottom: 16px;
}
.tasks-board__icon[data-v-d5100cc6] {
  width: 32px; height: 32px; border-radius: 8px;
