  display: flex; align-items: center; justify-content: center;
}
.tasks-board__title[data-v-d5100cc6] { font-size: 15px; font-weight: 700; color: var(--color-text-primary, #1a1a2e); margin: 0; padding: 0; border: none;
}
.tasks-board__count[data-v-d5100cc6] { font-size: 11px; font-weight: 600; background: var(--accent-bg); color: var(--accent-strong); padding: 2px 8px; border-radius: 8px;
}

