  background: linear-gradient(135deg, var(--accent), var(--accent-hover));
  color: #fff; font-size: 11px; font-weight: 700;
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.task-detail__comment-author[data-v-d5100cc6] { font-size: 12px; font-weight: 600; color: var(--color-text-primary);
}
.task-detail__comment-date[data-v-d5100cc6] { font-size: 11px; color: var(--color-text-muted);
}
.task-detail__comment-body[data-v-d5100cc6] { font-size: 13px; color: var(--color-text-secondary); line-height: 1.5; white-space: pre-wrap; word-break: break-word;
}

/* Attachments */
.task-detail__attachments[data-v-d5100cc6] { display: flex; flex-direction: column; gap: 6px;
}
.task-detail__attachment[data-v-d5100cc6] {
  display: flex; align-items: center; gap: 8px;
