  margin-top: 16px;
  border-top: 1px solid var(--color-border);
}
.tasks-board__page-btn[data-v-d5100cc6] {
  color: var(--accent);
}
.tasks-board__page-info[data-v-d5100cc6] { font-size: 12px; font-weight: 600; color: var(--color-text-secondary, #6b7280);
